from solution import Entry, Report, solve

assert solve([]) == Report(0, 0, 0), 'fixture 0'
assert solve([Entry(3, 8)]) == Report(0, 8, 0), 'fixture 1'
assert solve([Entry(1, 6), Entry(3, 7)]) == Report(0, 13, 0), 'fixture 2'
assert solve([Entry(2, 11), Entry(0, 0), Entry(0, (-2))]) == Report(0, 11, 2), 'fixture 3'
assert solve([Entry(3, 10), Entry(2, 2), Entry(4, 0), Entry(0, 11)]) == Report(1, 23, 0), 'fixture 4'
assert solve([Entry(3, 10), Entry(0, 5), Entry(4, 2), Entry(1, 3), Entry(1, 1)]) == Report(0, 21, 0), 'fixture 5'
assert solve([Entry(3, 5), Entry(1, (-2)), Entry(3, 11), Entry(4, 2), Entry(0, 10), Entry(3, 6)]) == Report(0, 34, 2), 'fixture 6'
assert solve([Entry(1, 5), Entry(1, 1), Entry(3, (-1)), Entry(0, 8), Entry(3, 7), Entry(0, 5), Entry(1, 11)]) == Report(0, 36, 0), 'fixture 7'
assert solve([Entry(0, (-3)), Entry(1, 7), Entry(1, 7), Entry(3, (-2)), Entry(4, (-1)), Entry(0, 4), Entry(2, 8), Entry(1, (-2))]) == Report(0, 21, 3), 'fixture 8'
assert solve([Entry(2, 10), Entry(2, 11), Entry(4, 2), Entry(3, 1), Entry(2, 1), Entry(2, 4), Entry(0, 2), Entry(3, (-3)), Entry(4, 2)]) == Report(0, 32, 2), 'fixture 9'
assert solve([Entry(0, 7), Entry(3, (-3)), Entry(1, 5), Entry(0, 10), Entry(1, 8), Entry(3, 6), Entry(0, 2), Entry(4, 5), Entry(2, (-1)), Entry(0, 1)]) == Report(0, 41, 1), 'fixture 10'
assert solve([Entry(2, 5), Entry(4, 3), Entry(3, 11), Entry(1, 8), Entry(3, 4), Entry(0, 1), Entry(4, 3), Entry(1, 5), Entry(4, 6), Entry(1, 9), Entry(4, 7)]) == Report(0, 62, 0), 'fixture 11'
assert solve([Entry(1, 3), Entry(1, 7), Entry(3, 4), Entry(2, 6), Entry(2, 11), Entry(1, 0), Entry(0, 2), Entry(1, 10), Entry(1, (-1)), Entry(0, (-1)), Entry(3, 11), Entry(3, (-3))]) == Report(0, 49, 0), 'fixture 12'
assert solve([Entry(3, (-1))]) == Report(0, 0, 1), 'fixture 13'
assert solve([Entry(0, 4), Entry(4, 8)]) == Report(0, 12, 0), 'fixture 14'
assert solve([Entry(3, 7), Entry(0, (-1)), Entry(0, 3)]) == Report(0, 9, 0), 'fixture 15'
assert solve([Entry(1, 11), Entry(0, 5), Entry(3, 4), Entry(0, 4)]) == Report(0, 24, 0), 'fixture 16'
assert solve([Entry(1, 1), Entry(2, 5), Entry(4, (-3)), Entry(2, 5), Entry(1, (-3))]) == Report(0, 10, 5), 'fixture 17'
assert solve([Entry(0, 4), Entry(2, 1), Entry(3, 10), Entry(4, (-3)), Entry(2, 4), Entry(1, 4)]) == Report(0, 23, 3), 'fixture 18'
assert solve([Entry(2, 1), Entry(0, 6), Entry(1, 6), Entry(0, 0), Entry(1, 0), Entry(2, 11), Entry(4, (-1))]) == Report(0, 24, 1), 'fixture 19'
assert solve([Entry(4, 6), Entry(4, (-1)), Entry(0, (-3)), Entry(2, 9), Entry(0, (-1)), Entry(0, 2), Entry(1, (-2)), Entry(1, (-1))]) == Report(0, 14, 5), 'fixture 20'
assert solve([Entry(1, 0)]) == Report(1, 0, 0), 'fixture 21'
assert solve([Entry(1, (-3)), Entry(1, 3), Entry(2, (-1)), Entry(3, 2)]) == Report(1, 2, 1), 'fixture 22'
assert solve([Entry(1, 5), Entry(2, (-4)), Entry(1, (-5)), Entry(3, 7)]) == Report(1, 7, 4), 'fixture 23'
